		if q := r.URL.Query(); q.Has("active") {
			var active bool
			switch q.Get("active") {
			case "true":
				active = true
			case "false":
				active = false
			default:
				http.Error(w, `invalid value for query parameter "active"`, http.StatusBadRequest)
				return
			}
			filtered := make([]Account, 0, len(sorted))
			for _, a := range sorted {
				if a.Active == active {
					filtered = append(filtered, a)
				}
			}
			result = filtered
		}
		writeJSON(w, http.StatusOK, result)
	})
