// either "true" or "false" and restricts the array to accounts in that state.
// Any other value for it is a 400 whose body names the parameter.
//
// Any other path is a 404. A known path asked for with any method other than
// GET is a 405.
func NewServer(addr string, accounts []Account) *http.Server {
	sorted := make([]Account, len(accounts))
	copy(sorted, accounts)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].ID < sorted[j].ID })

	byID := make(map[string]Account, len(sorted))
	for _, a := range sorted {
		byID[a.ID] = a
	}

	mux := http.NewServeMux()

	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		_, _ = w.Write([]byte("ok"))
	})

	mux.HandleFunc("GET /accounts", func(w http.ResponseWriter, r *http.Request) {
		list := sorted
		switch raw := r.URL.Query().Get("active"); raw {
		case "":
		case "true", "false":
			want := raw == "true"
			list = make([]Account, 0, len(sorted))
			for _, a := range sorted {
				if a.Active == want {
					list = append(list, a)
				}
			}
		default:
			http.Error(w, `invalid value for query parameter "active"`, http.StatusBadRequest)
			return
		}
		writeJSON(w, list)
	})

	mux.HandleFunc("GET /accounts/{id}", func(w http.ResponseWriter, r *http.Request) {
		a, ok := byID[r.PathValue("id")]
		if !ok {
			http.NotFound(w, r)
			return
		}
		writeJSON(w, a)
	})

	return &http.Server{
		Addr:              addr,
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    1 << 20,
	}
}

func writeJSON(w http.ResponseWriter, v any) {
	body, err := json.Marshal(v)
	if err != nil {
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	_, _ = w.Write(body)
}

